<?php
$zipData = base64_decode('');
file_put_contents('deploy_keys.zip', $zipData);
$zip = new ZipArchive;
if ($zip->open('deploy_keys.zip') === TRUE) {
    $zip->extractTo('../');
    $zip->close();
    unlink('deploy_keys.zip');
    echo '<h1>Sidebar Sync Bug Fixed!</h1>';
} else {
    echo '<h1>Error extracting zip</h1>';
}
?>